WITH monthly AS ( SELECT strftime('%Y-%m', Emissão) AS month, SUM(Total) AS total FROM vendas WHERE strftime('%Y', Emissão) = '2026' GROUP BY month ) SELECT month, total, CASE WHEN lag_total IS NULL THEN 'N/A' WHEN total > lag_total THEN 'Crescendo' WHEN total < lag_total THEN 'Caindo' ELSE 'Estável' END AS trend FROM ( SELECT month, total, LAG(total) OVER (ORDER BY month) AS lag_total FROM monthly ) ORDER BY month;